/**
 * CUSTIMESH - Gomulu Cevrimdisi Cekirdek Verileri (Rev16 + v4.8)
 * - Manifold-3D WebAssembly Geometri Cekirdegi (WASM)
 * - Bagimsiz Hekim Goruntuleyici HTML Sablonu (Gzip + Base64)
 */
(function() {
  const blobs = [
    ["doctor-template", ''],
    ["cm-kernel-js", ''],
    ["cm-kernel-wasm", '']
  ];
  for (const [id, data] of blobs) {
    let el = document.getElementById(id);
    if (!el) {
      el = document.createElement("script");
      el.id = id;
      el.type = "application/octet-stream";
      el.textContent = data;
      document.body.appendChild(el);
    }
  }
})();